// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';
import { Iterator as Iter, IterableIterator } from '@stdlib/types/iter';

// Define a union type representing both iterable and non-iterable iterators:
type Iterator = Iter | IterableIterator;

/**
* Returns an iterator which iterates over the Cartesian product of two array-like objects.
*
* ## Notes
*
* -   The order of the returned tuples follows the order of iteration of the provided array-like objects, with elements of the second array-like object varying fastest.
* -   If provided one or more empty array-like objects, the returned iterator is empty.
* -   If an environment supports `Symbol.iterator`, the returned iterator is iterable.
*
* @param x1 - first input array
* @param x2 - second input array
* @throws first argument must be an array-like object
* @throws second argument must be an array-like object
* @returns iterator
*
* @example
* var iter = iterCartesianProduct( [ 1, 2, 3 ], [ 4, 5 ] );
*
* var v = iter.next().value;
* // returns [ 1, 4 ]
*
* v = iter.next().value;
* // returns [ 1, 5 ]
*
* v = iter.next().value;
* // returns [ 2, 4 ]
*
* // ...
*/
declare function iterCartesianProduct( x1: Collection, x2: Collection ): Iterator;


// EXPORTS //

export = iterCartesianProduct;
